import { Project } from '../../src'
import { type FileSystem, Formatter, JSON5 } from '@servicenow/sdk-build-core'
import memfs from 'memfs'

describe('Prettier config loading', () => {
    test('should load all prettier config formats', async () => {
        const source = `import { ScriptInclude } from '@servicenow/sdk/core'
ScriptInclude({
  $id: Now.ID['test1'],
  name: 'test',
  script: "gs.info('hi');",
  clientCallable: true,
  mobileCallable: false,
  sandboxCallable: false,
  active: false,
})`

        const expected = `import { ScriptInclude } from "@servicenow/sdk/core";
ScriptInclude({
  $id: Now.ID["test1"],
  name: "test",
  script: "gs.info('hi');",
  clientCallable: true,
  mobileCallable: false,
  sandboxCallable: false,
  active: false,
});
`

        const prettierConfigs = [
            { filePath: '/.prettierrc', content: JSON.stringify({ semi: true, singleQuote: false }) },
            { filePath: '/.prettierrc.json', content: JSON.stringify({ semi: true, singleQuote: false }) },
            { filePath: '/.prettierrc.json5', content: JSON5.stringify({ semi: true, singleQuote: false }) },
        ]

        for (const config of prettierConfigs) {
            const result = await formatContent(config, source)
            expect(result).toEqual(expected)
        }
    })
})

async function formatContent(prettierFile: { content: string; filePath: string }, content: string): Promise<string> {
    const vol = new memfs.Volume()
    const fs = memfs.createFsFromVolume(vol) as FileSystem

    fs.writeFileSync(prettierFile.filePath, prettierFile.content)

    const project = new Project({
        config: {
            scope: 'x_snc_test',
            scopeId: 'aaaa1111bbbb2222cccc3333dddd4444',
        },
        packageJson: {
            name: 'x_snc_test',
            version: '1.0.0',
        },
        rootDir: '/',
        fileSystem: fs,
    })

    const file = project.addFile({
        path: '/src/fluent/source.now.ts',
        content,
    })
    file.save()

    const formatter = new Formatter(fs)
    await file.format(formatter)

    return file.getContent()
}
